using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;using Microsoft.EntityFrameworkCore;using System.Security.Claims;using System.Data;using EMedicine.Api.Data;using EMedicine.Api.Models;using EMedicine.Api.DTOs;
namespace EMedicine.Api.Controllers;
[ApiController][Authorize][Route("api/orders")]public class OrdersController(AppDbContext db):ControllerBase{int Uid=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
[HttpGet]public async Task<IActionResult> Mine()=>Ok(await db.Orders.Include(x=>x.Items).Where(x=>x.UserId==Uid).OrderByDescending(x=>x.CreatedOn).ToListAsync());
[HttpPost]public async Task<IActionResult> Checkout(){await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var cart=await db.Cart.Include(x=>x.Medicine).Where(x=>x.UserId==Uid).ToListAsync();if(cart.Count==0)return BadRequest("Cart is empty");foreach(var c in cart)if(c.Medicine==null||!c.Medicine.Active||c.Medicine.ExpDate.Date<DateTime.UtcNow.Date||c.Quantity>c.Medicine.Quantity)return BadRequest("One or more items are unavailable");var order=new Order{UserId=Uid,OrderNumber="EM-"+Guid.NewGuid().ToString("N")[..10].ToUpperInvariant()};foreach(var c in cart){var m=c.Medicine!;var price=decimal.Round(m.UnitPrice*c.Quantity*(100-m.Discount)/100,2);order.Items.Add(new OrderItem{MedicineId=m.Id,MedicineName=m.Name,UnitPrice=m.UnitPrice,Discount=m.Discount,Quantity=c.Quantity,TotalPrice=price});order.Total+=price;m.Quantity-=c.Quantity;}db.Orders.Add(order);db.Cart.RemoveRange(cart);await db.SaveChangesAsync();await tx.CommitAsync();return Ok(order);}
[Authorize(Roles="Admin")][HttpGet("admin")]public async Task<IActionResult> All()=>Ok(await db.Orders.Include(x=>x.Items).OrderByDescending(x=>x.CreatedOn).ToListAsync());
[Authorize(Roles="Admin")][HttpPatch("{id:int}/status")]public async Task<IActionResult> Status(int id,StatusRequest r){if(!new[]{"Placed","Pending","Processing","Dispatched","Shipped","Delivered","Cancelled"}.Contains(r.Status))return BadRequest("Invalid status");var o=await db.Orders.FindAsync(id);if(o==null)return NotFound();if(o.Status=="Cancelled"&&r.Status!="Cancelled")return BadRequest("Cancelled order cannot be reopened");o.Status=r.Status;await db.SaveChangesAsync();return Ok(o);}}
